WITH member_expense_counts AS (SELECT m.member_id, COUNT(*) as expense_count, SUM(CASE WHEN e.approved::boolean THEN 1 ELSE 0 END) as approved_count FROM expense e JOIN member m ON e.link_to_member = m.member_id GROUP BY m.member_id) SELECT m.first_name, m.last_name, mec.expense_count, mec.approved_count, ROUND(mec.approved_count::numeric / NULLIF(mec.expense_count, 0) * 100, 2) as approval_rate FROM member_expense_counts mec JOIN member m ON mec.member_id = m.member_id ORDER BY mec.approved_count DESC LIMIT 50;
